class Solution:
    def findLonely(self, nums: List[int]) -> List[int]:
        count = collections.Counter(nums)
        return [x for x, cnt in count.items() if cnt == 1 and (x - 1) not in count and (x + 1) not in count]

class Solution {
public:
    vector<int> findLonely(vector<int>& nums) {
        unordered_map<int, int> count;
        for (int x : nums) count[x]++;
        vector<int> res;
        for (auto& [x, cnt] : count) {
            if (cnt == 1 && !count.count(x - 1) && !count.count(x + 1)) {
                res.push_back(x);
            }
        }
        return res;
    }
};

class Solution {
    public List<Integer> findLonely(int[] nums) {
        Map<Integer, Integer> count = new HashMap<>();
        for (int x : nums) count.put(x, count.getOrDefault(x, 0) + 1);
        List<Integer> res = new ArrayList<>();
        for (Map.Entry<Integer, Integer> entry : count.entrySet()) {
            int x = entry.getKey();
            int cnt = entry.getValue();
            if (cnt == 1 && !count.containsKey(x - 1) && !count.containsKey(x + 1)) {
                res.add(x);
            }
        }
        return res;
    }
}

var findLonely = function(nums) {
    const count = new Map();
    for (const x of nums) count.set(x, (count.get(x) || 0) + 1);
    const res = [];
    for (const [x, cnt] of count.entries()) {
        if (cnt === 1 && !count.has(x - 1) && !count.has(x + 1)) {
            res.push(x);
        }
    }
    return res;
};
